print(f"Dataset 2018 preparado: {len(DATA_2018_RAW)} prospectos.")

def format_class(raw_list, year):
    out = []
    for item in raw_list:
        bio = item["bio"]
        s = item["s"]
        hist = item["hist"]
        pick_num = item["pick"]
        rnd = 1 if pick_num <= 30 else 2
        entry = {
            "player": item["p"],
            "class_year": year,
            "round": rnd,
            "pick": pick_num,
            "position": item["pos"],
            "target_team_and_pick": item["team"],
            "origin": item["org"],
            "age_at_draft": item["age"],
            "biometrics": {
                "height": bio[0],
                "wingspan": bio[1],
                "weight": bio[2],
                "vertical_max": bio[3],
                "wingspan_differential": bio[4]
            },
            "stats": {
                "PTS": s[0],
                "AST": s[1],
                "REB": s[2],
                "STL": s[3],
                "BLK": s[4],
                "TS%": s[5],
                "eFG%": s[6],
                "USG%": s[7],
                "AST_TO": s[8],
                "3P%": s[9],
                "3PA": s[10],
                "FT%": s[11],
                "FTA": s[12],
                "BPM_est": s[13]
            },
            "scout_reports": {
                "strengths": item["str"],
                "concerns": item["con"]
            },
            "historical_reality": {
                "nba_pick": hist[0],
                "career_arc": hist[1],
                "all_star_appearances": hist[2],
                "historical_verdict": hist[3]
            }
        }
        out.append(entry)
    return out

dataset_2017 = format_class(DATA_2017_RAW, 2017)
dataset_2018 = format_class(DATA_2018_RAW, 2018)

data_dir = Path("data")
data_dir.mkdir(exist_ok=True)

with open(data_dir / "draft_2017.json", "w", encoding="utf-8") as f:
    json.dump(dataset_2017, f, indent=2, ensure_ascii=False)

with open(data_dir / "draft_2018.json", "w", encoding="utf-8") as f:
    json.dump(dataset_2018, f, indent=2, ensure_ascii=False)

print(f"Sucesso! Gerados {len(dataset_2017)} jogadores em data/draft_2017.json")
print(f"Sucesso! Gerados {len(dataset_2018)} jogadores em data/draft_2018.json")
print("Total geral: 120 prospectos na base completa do Draft da NBA (2017-2018).")

